    elif line.startswith('## ') and not line.startswith('## Chapter ') and not line.startswith('## Copyright') and not line.startswith('## Contents') and not line.startswith('## A Note') and not line.startswith('## About') and not line.startswith('## Also from') and not line.startswith('## The Closing'):
